from typing import List
from itertools import product, repeat

def maxScoreWords(words: List[str], letters: List[str], score: List[int]) -> int:
    letter_counts = [0] * 26
    for letter in letters:
        letter_counts[ord(letter) - ord('a')] += 1

    max_score = 0
    for word_combo in product(*(repeat(w, min(w.count(c), letters.count(c)) for c in set(w)) for w in words)):
        word_counts = [0] * 26
        for word in word_combo:
            for letter in word:
                word_counts[ord(letter) - ord('a')] += 1

        if all(word_counts[i] <= letter_counts[i] for i in range(26)):
            current_score = sum(score[ord(c) - ord('a')] * word_counts[ord(c) - ord('a')] for c in set(''.join(word_combo)))
            max_score = max(max_score, current_score)

    return max_score
